from pathlib import Path
import subprocess
p=Path(__file__).parent
base='''<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="1024" viewBox="0 0 1024 1024"><defs><linearGradient id="bg" x2=".85" y2="1"><stop stop-color="COLOR1"/><stop offset=".55" stop-color="COLOR2"/><stop offset="1" stop-color="COLOR3"/></linearGradient><linearGradient id="glass" x2=".7" y2="1"><stop stop-color="white" stop-opacity=".85"/><stop offset="1" stop-color="white" stop-opacity=".2"/></linearGradient><linearGradient id="edge" x2="0" y2="1"><stop stop-color="white" stop-opacity=".8"/><stop offset="1" stop-color="white" stop-opacity=".12"/></linearGradient><filter id="shadow" x="-40%" y="-40%" width="180%" height="180%"><feDropShadow dx="0" dy="14" stdDeviation="12" flood-color="#052956" flood-opacity=".3"/></filter></defs><rect x="100" y="100" width="824" height="824" rx="190" fill="url(#bg)"/><rect x="104" y="104" width="816" height="816" rx="186" fill="none" stroke="url(#edge)" stroke-width="5"/>ART</svg>'''
spark='<path d="M752 235 Q752 302 690 310 Q752 318 752 383 Q760 318 822 310 Q760 302 752 235Z" fill="white"/>'
arts=[('01-clean-screen',['#42d6f4','#187dea','#6451d9'],'''<g filter="url(#shadow)"><rect x="250" y="306" width="524" height="366" rx="46" fill="#073c88"/><rect x="269" y="325" width="486" height="328" rx="29" fill="url(#glass)" stroke="white" stroke-opacity=".7" stroke-width="5"/><path d="M474 678H550L565 724H459Z" fill="#c9edff"/><rect x="404" y="720" width="216" height="24" rx="12" fill="white"/><path d="M327 564L485 406" stroke="white" stroke-opacity=".32" stroke-width="32" stroke-linecap="round"/></g>'''+spark),('02-clean-shield',['#9ceafa','#439eef','#5153cc'],'''<g filter="url(#shadow)"><path d="M512 247 Q627 318 729 327V493Q724 671 512 788Q300 671 295 493V327Q397 318 512 247Z" fill="url(#glass)" stroke="white" stroke-opacity=".8" stroke-width="7"/><path d="M445 483V434A67 67 0 0 1 579 434V483" fill="none" stroke="#195cb3" stroke-width="31" stroke-linecap="round"/><rect x="409" y="472" width="206" height="164" rx="34" fill="#195cb3"/><circle cx="512" cy="538" r="19" fill="white"/><path d="M512 548V578" stroke="white" stroke-width="18" stroke-linecap="round"/></g>'''+spark),('03-wipe-key',['#3748ad','#605cdb','#b08bed'],'''<g filter="url(#shadow)"><rect x="265" y="280" width="494" height="464" rx="96" fill="url(#glass)" stroke="white" stroke-opacity=".8" stroke-width="6"/><path d="M319 590L500 408Q522 386 546 408L670 532Q692 554 670 577L489 758Z" fill="#b7f5ff"/><path d="M319 590L489 758L451 796Q429 817 407 795L281 669Q259 647 281 625Z" fill="#62d5ef"/><path d="M365 579L511 433" stroke="white" stroke-opacity=".65" stroke-width="12" stroke-linecap="round"/></g>'''+spark)]
for name,colors,art in arts:
 s=base.replace('ART',art)
 for i,c in enumerate(colors,1): s=s.replace('COLOR'+str(i),c)
 (p/(name+'.svg')).write_text(s)
 for size in (1024,64): subprocess.run(['rsvg-convert','-w',str(size),'-h',str(size),'-o',str(p/f'{name}-{size}.png'),str(p/(name+'.svg'))],check=True)
